  pane.innerHTML='<div class="phead"><div><small class="kick">'+t('last')+': '+(p.last?esc(ago(p.last)):'—')+'</small><h1>'+esc(p.name)+'</h1></div>'
    +'<div class="acts"><button onclick="optim()">'+I.bolt+' '+t('optimize')+'</button>'+playBtn()+'</div></div>'
    +'<div class="facts">'
    +'<div class="click" tabindex="0" role="button" title="'+esc(t('edit'))+'" onclick="verDlg()" onkeydown="if(event.key===\'Enter\')verDlg()"><small>'+t('m_ver')+'</small><b>'+esc(p.mc)+'</b><span class="ed">'+NXI.edit+'</span></div>'
    +'<div><small>'+t('m_loader')+'</small><b>'+esc(p.loader)+'</b></div>'
